import React, { useState, useEffect } from 'react';
import { apiCall } from '../../../../api';
import { toast } from '../../../../toast';
import { setupCalcHandlers } from '../../../../calc';
import FormRenderer from '../../../../components/FormRenderer';

// frmCustomer — Add/Edit Page (master)
// Auto-generated by Form Generator

function AddEditPage({ formId, recordId, config, onBack }) {
  const [bootData, setBootData] = useState(null);
  const [formData, setFormData] = useState({});
  const [detailData, setDetailData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isLocked, setIsLocked] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const headerFields = [
    { name: 'LedgerCode', label: 'Ledger Code', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'LedgerGroup', label: 'Ledger Group', type: 'select', width: '6,6,6,6', source: 'LedgerGroup', classes: '' },
    { name: 'Alias', label: 'Alias', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'Currency', label: 'Currency', type: 'select', width: '6,6,6,6', source: 'Currency', classes: '' },
    { name: 'Country', label: 'Country', type: 'select', width: '6,6,6,6', source: 'Country', classes: '' },
    { name: 'Add1', label: 'Address 1', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'Add2', label: 'Address 2', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'City', label: 'City', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'State', label: 'State', type: 'select', width: '6,6,6,6', source: 'State', classes: '' },
    { name: 'PinCode', label: 'Pin Code', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'ContactDescription', label: 'Contact', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'Phone', label: 'Phone', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'Email', label: 'Email', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'WhatsAppNo', label: 'WhatsApp', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'CustomerGroup', label: 'Customer Group', type: 'select', width: '6,6,6,6', source: 'CustomerGroup', classes: '' },
    { name: 'CrLimit', label: 'Credit Limit', type: 'number', width: '6,6,6,6', source: '', classes: '' },
    { name: 'PmntTerm', label: 'Payment Term', type: 'select', width: '6,6,6,6', source: 'PmntTerm', classes: '' },
    { name: 'PmntMethod', label: 'Payment Method', type: 'select', width: '6,6,6,6', source: 'PmntMethod', classes: '' },
    { name: 'DeliveryTerm', label: 'Delivery Term', type: 'select', width: '6,6,6,6', source: 'DeliveryTerm', classes: '' },
    { name: 'DeliveryMode', label: 'Delivery Mode', type: 'select', width: '6,6,6,6', source: 'DeliveryMode', classes: '' },
    { name: 'GstIn', label: 'GSTIN', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'PAN', label: 'PAN', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'BankaName', label: 'Bank Name', type: 'select', width: '6,6,6,6', source: 'BankaName', classes: '' },
    { name: 'BankAc', label: 'Bank Account', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'IFSC', label: 'IFSC', type: 'text', width: '6,6,6,6', source: '', classes: '' },
    { name: 'Transport', label: 'Transport', type: 'select', width: '6,6,6,6', source: 'Transport', classes: '' },
    { name: 'IsCustomer', label: 'Is Customer', type: 'checkbox', width: '6,6,6,6', source: '', classes: '' },
    { name: 'IsSupplier', label: 'Is Supplier', type: 'checkbox', width: '6,6,6,6', source: '', classes: '' },
    /* ash1-only: TestField is the 29th header field. Its position here has to
       agree with src/companies/ash1/fieldOrder.json ("header.append") and with
       the p_testfield parameter in sql/01_frmcustomer_testfield.sql - the sp_*
       procs are called positionally, so a mismatch here writes TestField's
       value into IsSupplier instead of erroring. */
    { name: 'TestField', label: 'Test Field (ash1 only)', type: 'text', width: '6,6,6,6', source: '', classes: '' }
  ];




  useEffect(() => { setupCalcHandlers(); loadData(); }, [formId, recordId]);

  const loadData = async () => {
    setLoading(true);
    try {
      const boot = await apiCall('_BOOT', formId, {});
      setBootData(boot);
      if (!recordId && Array.isArray(headerFields)) {
        const init = {};
        headerFields.forEach(f => { init[f.name] = f.type === 'checkbox' ? false : ''; });
        setFormData(init);
      }
      if (recordId) {
        const ed = await apiCall('_EDIT_JSON', formId, { id: recordId });
        if (ed.hdr1?.[0]) { setFormData(ed.hdr1[0]); setIsLocked(!!ed.hdr1[0].LOCK); }

      }
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const handleChange = (name, val) => setFormData(p => ({ ...p, [name]: val }));

  const save = async () => {
    setSaving(true);
    setStatusMsg('Saving...');
    try {
      const action = recordId ? '_UPDATE' : '_SAVE';
      const body = recordId ? { id: recordId, params: formData } : { params: formData };
      const r = await apiCall(action, formId, body);
      if (r?.det1?.[0]?.Error) { setStatusMsg('Error: ' + r.det1[0].Error); }
      else { setStatusMsg('Saved!'); toast('Saved successfully', 'success'); onBack(); }
    } catch (e) { setStatusMsg('Error: ' + e.message); toast('Save failed', 'error'); }
    finally { setSaving(false); }
  };

  const lockUnlock = async () => {
    try {
      await apiCall('_LOCK', formId, { id: recordId, params: { id: recordId } });
      setIsLocked(!isLocked);
      toast(isLocked ? 'Unlocked' : 'Locked', 'success');
    } catch (e) { toast('Lock failed', 'error'); }
  };

  const deleteRecord = async () => {
    if (!confirm('Delete this record?')) return;
    try {
      await apiCall('_DELETE', formId, { id: recordId });
      toast('Deleted', 'success');
      onBack();
    } catch (e) { toast('Delete failed', 'error'); }
  };

  if (loading) return <div className="page-content text-center py-5"><div className="spinner-border"></div></div>;

  return (
    <div className="page-content animate-fade">
      <div className="card mb-3">
        <div className="card-header d-flex justify-content-between align-items-center">
          <span><strong>Customer Master</strong></span>
          {recordId && (
            <span className={`badge-status ${isLocked ? 'badge-locked' : 'badge-draft'}`}>
              {isLocked ? 'LOCKED' : 'Draft'} — ID: {recordId}
            </span>
          )}
        </div>
        <div className="card-body">
          <FormRenderer fields={headerFields} data={formData} bootData={bootData} onChange={handleChange} readOnly={isLocked} />
        </div>
      </div>



      <div className="action-bar">
        <button className="btn btn-outline-secondary btn-sm" onClick={onBack}>
          <i className="bi bi-arrow-left"></i> Back
        </button>
        <div className="d-flex gap-2 align-items-center">
          {statusMsg && <span style={{fontSize:11, color:'var(--text-secondary)'}}>{statusMsg}</span>}
          {!isLocked && recordId && (
            <>
              <button className="btn btn-danger btn-sm" onClick={deleteRecord}><i className="bi bi-trash"></i></button>
              <button className="btn btn-info btn-sm text-white" onClick={lockUnlock}><i className="bi bi-lock"></i> Lock</button>
            </>
          )}
          {isLocked && (
            <button className="btn btn-warning btn-sm" onClick={lockUnlock}><i className="bi bi-unlock"></i> Unlock</button>
          )}
          {!isLocked && (
            <button className="btn btn-primary btn-sm" onClick={save} disabled={saving}>
              {saving ? <span className="spinner-border spinner-border-sm"></span> : <><i className="bi bi-save"></i> Save</>}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default AddEditPage;
